diff --git a/packages/workflow/test/workflow-expression.test.ts b/packages/workflow/test/workflow-expression.test.ts
index 1a27cf63d..ac9ed3923 100644
--- a/packages/workflow/test/workflow-expression.test.ts
+++ b/packages/workflow/test/workflow-expression.test.ts
@@ -45,4 +45,55 @@ describe('WorkflowExpression', () => {
 			expect(result).toEqual({ key: 'title|display', type: 'display' });
 		});
 	});
+
+	describe('$self in expression-mode parameters', () => {
+		const nodeTypes = Helpers.NodeTypes();
+		const workflow = new Workflow({
+			id: '1',
+			nodes: [
+				{
+					name: 'node',
+					typeVersion: 1,
+					type: 'test.set',
+					id: 'uuid-1234',
+					position: [0, 0],
+					parameters: {
+						value1: '={{ $self.apiHost }}',
+					},
+				},
+			],
+			connections: {},
+			active: false,
+			nodeTypes,
+		});
+		const expression = workflow.expression;
+
+		beforeAll(async () => {
+			await expression.acquireIsolate();
+		});
+		afterAll(async () => {
+			await expression.releaseIsolate();
+		});
+
+		it('should resolve $self inside a parameter referenced via $parameter', () => {
+			// e.g. a credential template field `={{ $parameter.value1 }}` whose stored
+			// value is `={{ $self.apiHost }}` must see the same selfData as the caller.
+			const result = expression.getParameterValue(
+				'={{ $parameter.value1 }}',
+				null,
+				0,
+				0,
+				'node',
+				[],
+				'manual',
+				{},
+				undefined,
+				false,
+				{ apiHost: 'example.com' },
+			);
+
+			expect(result).toEqual('example.com');
+		});
+
+	});
 });
